package com.nanum.investment.domain;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="\"TB_PRC_DAY\"",uniqueConstraints=@UniqueConstraint(name="UK_TB_PRC_DAY_01",columnNames={"STK_ID","TRADE_DT"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class TbPrcDay { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="PRC_DAY_ID") private Long dailyPriceId; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="STK_ID",nullable=false) private TbStk stock; @Column(name="TRADE_DT",nullable=false) private LocalDate tradeDate; @Column(name="OPEN_PRC",precision=20,scale=6) private BigDecimal openPrice; @Column(name="HIGH_PRC",precision=20,scale=6) private BigDecimal highPrice; @Column(name="LOW_PRC",precision=20,scale=6) private BigDecimal lowPrice; @Column(name="CLS_PRC",nullable=false,precision=20,scale=6) private BigDecimal closePrice; @Column(name="ADJ_CLS_PRC",precision=20,scale=6) private BigDecimal adjustedClosePrice; @Column(name="CHG_RT",precision=10,scale=4) private BigDecimal changeRate; @Column(name="DD_HIGH_RT",precision=10,scale=4) private BigDecimal drawdownFromHighRate; @Column(name="DATA_SRC_CD",nullable=false,length=30) private String dataSourceCode; @Enumerated(EnumType.STRING) @Builder.Default @Column(name="DATA_STS",nullable=false,length=20) private DataStatus dataStatus=DataStatus.FRESH; @Column(name="COLLECT_DTTM",insertable=false) private OffsetDateTime collectedDateTime; }
